window.MATH_CURRICULUM = {"id":"math-foundations","title":"数学基础知识地图","initialChapter":"1","source":"原创知识卡与练习","contentNote":"按知识点组织学习内容，可按自己的进度选择。","chapters":[{"id":"1","title":"数的整除","color":"green","icon":"mountain","intro":"认识因数与倍数，为约分和通分打好基础。"},{"id":"2","title":"分数","color":"blue","icon":"pie-chart","intro":"从分数的意义出发，学会运算与解决问题。"},{"id":"3","title":"比和比例","color":"purple","icon":"scale","intro":"用比、百分比和可能性理解生活中的数量关系。"},{"id":"4","title":"圆和扇形","color":"orange","icon":"circle","intro":"从半径、直径到周长、弧长与面积。"}],"lessons":[{"id":"1.1","chapter":"1","title":"整数和整除的意义","goal":"分清整数、自然数与整除，能判断一次除法是否属于整除。","concept":["整数包括正整数、零和负整数；自然数包括零和正整数。本章在没有特别说明时讨论正整数。","整除要看两个数和商：在本章的范围里，被除数、除数都是正整数，商是整数，而且没有余数。除数不能是零。"],"formula":"a ÷ b 的商是整数、没有余数 → a 能被 b 整除","pitfall":"没有余数的除法不一定属于本章说的整除，例如 4.8 ÷ 2＝2.4。","prerequisites":[],"example":{"question":"24 能被 6 整除吗？","steps":["先看两个数：24 和 6 都是正整数。","计算 24 ÷ 6＝4；商是整数，没有余数。"],"answer":"24 能被 6 整除。"},"practices":[{"type":"choice","text":"下列哪个数是自然数？","options":["−2","0","1/2"],"answer":"0","hint":"自然数包括零和正整数。","solution":"0 是自然数；−2 是负整数，1/2 不是整数。","unit":""},{"type":"choice","text":"哪一个算式表示整除？","options":["25 ÷ 4＝6.25","24 ÷ 6＝4","4.8 ÷ 2＝2.4"],"answer":"24 ÷ 6＝4","hint":"两个数与商都要符合本章的整数范围。","solution":"24 和 6 都是正整数，商 4 也是整数，没有余数。","unit":""},{"type":"number","text":"36 ÷ 9 的商是多少？","answer":4,"check":"36/9","hint":"想一想 9 乘几等于 36。","solution":"36 ÷ 9＝4，所以 36 能被 9 整除。","unit":""}]},{"id":"1.2","chapter":"1","title":"因数和倍数","goal":"从整除关系中同时说出谁是谁的因数、谁是谁的倍数。","concept":["如果 a 能被 b 整除，b 就是 a 的因数，a 是 b 的倍数。因数与倍数描述的是两个数之间的关系。","一个正整数的因数可以成对找，而且数量有限；它的正整数倍数可以继续列下去。"],"formula":"a＝b × c → b、c 是 a 的因数；a 是 b、c 的倍数","pitfall":"说“6 是因数”信息不完整，要说“6 是 24 的因数”。","prerequisites":["1.1"],"example":{"question":"找出 18 的全部正因数。","steps":["按乘积配对：1×18、2×9、3×6。","把每一对中的数列出，避免重复。"],"answer":"1、2、3、6、9、18。"},"practices":[{"type":"choice","text":"哪句话正确？","options":["6 是 24 的因数","24 是 6 的因数","6 是 24 的倍数"],"answer":"6 是 24 的因数","hint":"24＝6×4。","solution":"24 能被 6 整除，所以 6 是 24 的因数，24 是 6 的倍数。","unit":""},{"type":"number","text":"12 一共有几个正因数？","answer":6,"check":"6","hint":"按乘积成对找，别重复。","solution":"1×12、2×6、3×4，所以有 1、2、3、4、6、12，共 6 个。","unit":"个"},{"type":"number","text":"7 的第 4 个正整数倍数是多少？","answer":28,"check":"7*4","hint":"从 7×1 开始数。","solution":"7、14、21、28，第 4 个是 28。","unit":""}]},{"id":"1.3","chapter":"1","title":"能被 2、5 整除的数","goal":"根据个位数字判断能被 2 或 5 整除，并识别同时满足的数。","concept":["能被 2 整除的整数叫偶数，个位是 0、2、4、6、8。不能被 2 整除的整数叫奇数。","能被 5 整除的正整数，个位是 0 或 5；同时能被 2 和 5 整除的正整数，个位一定是 0。"],"formula":"被 2 整除看个位是否为偶数；被 5 整除看个位是否为 0 或 5","pitfall":"判断时看个位，不是看这个数中有没有 2 或 5。","prerequisites":["1.1"],"example":{"question":"235 能被 2、5 中的哪个数整除？","steps":["235 的个位是 5，不属于 0、2、4、6、8。","个位是 5，符合被 5 整除的特征。"],"answer":"能被 5 整除，不能被 2 整除。"},"practices":[{"type":"choice","text":"哪个数能被 2 整除？","options":["135","248","357"],"answer":"248","hint":"看个位。","solution":"248 的个位是 8，是偶数，所以能被 2 整除。","unit":""},{"type":"choice","text":"哪个数同时能被 2 和 5 整除？","options":["125","236","340"],"answer":"340","hint":"个位应同时符合两个条件。","solution":"340 的个位是 0，符合两个条件。","unit":""},{"type":"number","text":"在 1 到 20 的正整数中，有几个数能被 5 整除？","answer":4,"check":"20/5","hint":"从 5 开始列倍数。","solution":"5、10、15、20，共 4 个。","unit":"个"}]},{"id":"1.4","chapter":"1","title":"素数、合数与分解素因数","goal":"区分素数和合数，把合数表示成素因数相乘。","concept":["只有 1 和它本身两个正因数的正整数叫素数；有两个以上正因数的正整数叫合数。1 既不是素数，也不是合数。","分解素因数要把一个合数写成若干素数相乘，可以逐步用素数试除。最后每个因数都必须是素数。"],"formula":"例如：24＝2 × 2 × 2 × 3","pitfall":"1 不能算素因数；分解到 2×12 还没有完成，因为 12 是合数。","prerequisites":["1.2"],"example":{"question":"把 36 分解素因数。","steps":["36＝2×18，继续分解 18。","18＝2×9，9＝3×3。","把这些素因数连起来。"],"answer":"36＝2×2×3×3。"},"practices":[{"type":"choice","text":"哪个数是素数？","options":["1","21","29"],"answer":"29","hint":"检查是否只有两个正因数。","solution":"29 的正因数只有 1 和 29；21＝3×7，1 不是素数。","unit":""},{"type":"number","text":"24 分解素因数后，最大的素因数是多少？","answer":3,"check":"3","hint":"24＝2×2×2×3。","solution":"素因数只有 2 和 3，最大的素因数是 3。","unit":""},{"type":"choice","text":"哪一个是 60 的完整素因数分解？","options":["2×30","2×2×3×5","1×2×2×3×5"],"answer":"2×2×3×5","hint":"每个因数都必须是素数。","solution":"60＝2×2×3×5；30 不是素数，1 也不是素数。","unit":""}]},{"id":"1.5","chapter":"1","title":"公因数与最大公因数","goal":"找到两个数共同的因数，并选出最大的一个。","concept":["两个或多个整数共有的因数叫公因数，其中最大的叫最大公因数。","可以分别列因数找交集，也可以利用素因数分解，取共同素因数的较少次数相乘。"],"formula":"先找共同因数 → 再选最大；分数约分会用到它","pitfall":"“共同”指两个数都能被它整除，不是只符合其中一个。","prerequisites":["1.2","1.4"],"example":{"question":"求 12 与 18 的最大公因数。","steps":["12 的因数是 1、2、3、4、6、12。","18 的因数是 1、2、3、6、9、18。","共有 1、2、3、6，最大的为 6。"],"answer":"最大公因数是 6。"},"practices":[{"type":"number","text":"18 与 24 的最大公因数是多少？","answer":6,"check":"6","hint":"分别列因数，找共同的。","solution":"18 和 24 的公因数是 1、2、3、6，最大的为 6。","unit":""},{"type":"number","text":"36 与 48 的最大公因数是多少？","answer":12,"check":"12","hint":"共同素因数是两个 2 和一个 3。","solution":"36＝2×2×3×3，48＝2×2×2×2×3，共同部分为 2×2×3＝12。","unit":""},{"type":"number","text":"24 颗红珠与 36 颗黄珠，要分成尽可能多份，每份配色相同且没有剩余，最多分几份？","answer":12,"check":"12","hint":"份数必须同时是 24 与 36 的因数。","solution":"24 和 36 的最大公因数是 12，所以最多分 12 份，每份 2 颗红珠、3 颗黄珠。","unit":"份"}]},{"id":"1.6","chapter":"1","title":"公倍数与最小公倍数","goal":"找到共同的正整数倍数，用最小公倍数解决周期问题。","concept":["两个或多个整数共有的倍数叫公倍数，其中最小的正整数公倍数叫最小公倍数。","利用素因数分解时，每种素因数都要保留，次数取较多的。分数通分也会用到最小公倍数。"],"formula":"每种素因数取较多次数相乘 → 最小公倍数","pitfall":"最大公因数找“能分”，最小公倍数找“共同达到”；不能混用。","prerequisites":["1.2","1.4"],"example":{"question":"求 6 与 8 的最小公倍数。","steps":["6＝2×3，8＝2×2×2。","保留三个 2 和一个 3。"],"answer":"2×2×2×3＝24。"},"practices":[{"type":"number","text":"6 与 8 的最小公倍数是多少？","answer":24,"check":"2*2*2*3","hint":"取每种素因数的较多次数。","solution":"6＝2×3，8＝2³，所以最小公倍数为 2³×3＝24。","unit":""},{"type":"number","text":"12 与 18 的最小公倍数是多少？","answer":36,"check":"2*2*3*3","hint":"需要两个 2 和两个 3。","solution":"12＝2²×3，18＝2×3²，所以最小公倍数为 2²×3²＝36。","unit":""},{"type":"number","text":"两辆车每隔 10 分钟和 15 分钟发车，刚才同时发车，下次同时发车要过几分钟？","answer":30,"check":"30","hint":"找 10 和 15 的最小公倍数。","solution":"10 的倍数有 10、20、30；15 的倍数有 15、30，最早共同达到 30 分钟。","unit":"分钟"}]},{"id":"2.1","chapter":"2","title":"分数与除法","goal":"把整数除法写成分数，并理解分子和分母的含义。","concept":["把一个整体平均分成若干份，取其中若干份，可以用分数表示。分母表示平均分成几份，分子表示取了几份。","a 除以非零的 b 可以写成 a/b。分数也可以表示一个量相对于另一个量的关系。"],"formula":"a ÷ b＝a/b（b≠0）","pitfall":"必须平均分；分母不能为零。","prerequisites":["1.1"],"example":{"question":"3 米绳子平均分给 4 人，每人得到多少米？","steps":["求每人长度，用总长度除以人数。","3 ÷ 4 可以写成分数 3/4。"],"answer":"每人得到 3/4 米。"},"practices":[{"type":"number","text":"3 ÷ 4 的结果是多少？可以填写分数。","answer":0.75,"check":"3/4","hint":"除法可以写成分数。","solution":"3 ÷ 4＝3/4。","unit":""},{"type":"number","text":"9 米绳子平均分成 4 段，每段长多少米？","answer":2.25,"check":"9/4","hint":"用总长度除以段数。","solution":"9 ÷ 4＝9/4 米，也就是 2.25 米。","unit":"米"},{"type":"choice","text":"3/5 中，分母 5 表示什么？","options":["取了 5 份","把整体平均分成 5 份","整体有 5 个"],"answer":"把整体平均分成 5 份","hint":"分母负责说明如何平均分。","solution":"分母 5 表示整体平均分成 5 份，分子 3 表示取其中 3 份。","unit":""}]},{"id":"2.2","chapter":"2","title":"分数的基本性质","goal":"运用基本性质完成约分和通分，保持分数大小不变。","concept":["分子和分母同时乘或除以同一个非零数，分数的大小不变。","约分把分子、分母的公因数约去；通分把分母改成相同的数，常用分母的最小公倍数。"],"formula":"a/b＝(a×k)/(b×k)，k≠0","pitfall":"分子与分母要同时改变；同时加上同一个数不能保证分数不变。","prerequisites":["2.1","1.5","1.6"],"example":{"question":"把 12/18 约成最简分数。","steps":["12 与 18 的最大公因数是 6。","分子与分母同时除以 6。"],"answer":"12/18＝2/3。"},"practices":[{"type":"number","text":"5/8＝15/□，□ 应填多少？","answer":24,"check":"8*3","hint":"分子乘了 3，分母也乘 3。","solution":"5→15 是乘 3，所以 8×3＝24。","unit":""},{"type":"number","text":"12/18 约成最简分数后，分母是多少？","answer":3,"check":"18/6","hint":"分子分母同时除以最大公因数。","solution":"12 和 18 的最大公因数为 6，约分得 2/3，分母是 3。","unit":""},{"type":"number","text":"1/6 与 1/8 通分时，最小公分母是多少？","answer":24,"check":"24","hint":"求 6 和 8 的最小公倍数。","solution":"最小公倍数是 24，通分为 4/24 和 3/24。","unit":""}]},{"id":"2.3","chapter":"2","title":"分数的大小比较","goal":"选择同分母、同分子或通分的方法比较大小。","concept":["分母相同，分子大的分数大；分子相同且为正数，分母小的分数大。","分子分母都不同时，可以先通分，再比较分子。也可以借助 1/2 或 1 作参考。"],"formula":"先统一比较标准，再判断大小","pitfall":"分母大不代表分数大，平均分的份数越多，每份反而越小。","prerequisites":["2.2"],"example":{"question":"比较 3/4 与 5/8。","steps":["把 3/4 通分成 6/8。","6/8 的分子大于 5/8 的分子。"],"answer":"3/4＞5/8。"},"practices":[{"type":"choice","text":"3/4 □ 5/8，□ 应填什么？","options":["＞","＜","＝"],"answer":"＞","hint":"把 3/4 化成分母为 8 的分数。","solution":"3/4＝6/8，所以 6/8＞5/8。","unit":""},{"type":"choice","text":"4/7 □ 5/7，□ 应填什么？","options":["＞","＜","＝"],"answer":"＜","hint":"分母相同，比较分子。","solution":"4＜5，所以 4/7＜5/7。","unit":""},{"type":"choice","text":"3/5 □ 5/8，□ 应填什么？","options":["＞","＜","＝"],"answer":"＜","hint":"通分成分母为 40 的分数。","solution":"3/5＝24/40，5/8＝25/40，所以 3/5＜5/8。","unit":""}]},{"id":"2.4","chapter":"2","title":"分数的加减法","goal":"先通分，再加减分子，最后约分。","concept":["同分母分数相加减，分母不变，分子相加减。因为计算的是同样大小的“份”。","异分母分数不能直接加减分子，要先通分。计算后检查是否能约分。"],"formula":"同分母：a/c ± b/c＝(a±b)/c","pitfall":"分母表示每份的大小，加减时不能把分母也相加减。","prerequisites":["2.2","2.3"],"example":{"question":"计算 1/3＋1/4。","steps":["3 与 4 的最小公倍数是 12。","通分：1/3＝4/12，1/4＝3/12。","同分母相加，得到 7/12。"],"answer":"1/3＋1/4＝7/12。"},"practices":[{"type":"number","text":"1/3＋1/4＝？","answer":0.5833333333333334,"check":"1/3+1/4","hint":"先通分到分母 12。","solution":"4/12＋3/12＝7/12。","unit":""},{"type":"number","text":"5/6−1/4＝？","answer":0.5833333333333334,"check":"5/6-1/4","hint":"先通分到分母 12。","solution":"10/12−3/12＝7/12。","unit":""},{"type":"number","text":"3/8＋5/12＝？","answer":0.7916666666666666,"check":"3/8+5/12","hint":"8 与 12 的最小公倍数是 24。","solution":"9/24＋10/24＝19/24。","unit":""}]},{"id":"2.5","chapter":"2","title":"分数的乘法","goal":"理解求一个量的几分之几，并运用约分简化乘法。","concept":["分数乘分数，用分子相乘作分子、分母相乘作分母。计算前可以先约分。","求一个量的几分之几，通常用这个量乘对应的分数。先找清分数是相对于哪个量。"],"formula":"a/b × c/d＝(a×c)/(b×d)","pitfall":"与加法不同，乘法不用先通分；先约分能减少计算。","prerequisites":["2.2"],"example":{"question":"24 本书的 3/8 是多少本？","steps":["把全部 24 本书看作标准量。","求它的 3/8，用 24×3/8。","24 与 8 先约分，得到 3×3。"],"answer":"9 本。"},"practices":[{"type":"number","text":"2/3×9/10＝？","answer":0.6,"check":"2/3*9/10","hint":"先把 9 与 3 约分。","solution":"2/3×9/10＝18/30＝3/5。","unit":""},{"type":"number","text":"24 的 3/8 是多少？","answer":9,"check":"24*3/8","hint":"求一个量的几分之几，用乘法。","solution":"24×3/8＝9。","unit":""},{"type":"number","text":"1/2×3/5＝？","answer":0.3,"check":"1/2*3/5","hint":"分子相乘，分母相乘。","solution":"1×3/(2×5)＝3/10。","unit":""}]},{"id":"2.6","chapter":"2","title":"分数的除法","goal":"理解倒数，把除以非零分数转化为乘它的倒数。","concept":["乘积为 1 的两个数互为倒数，零没有倒数。","除以一个非零数，等于乘这个数的倒数。要取倒数的是除数，不是被除数。"],"formula":"a/b ÷ c/d＝a/b × d/c（除数≠0）","pitfall":"只有除数取倒数；如果除数是整数，也可以把它看成分母为 1 的分数。","prerequisites":["2.5"],"example":{"question":"计算 3/4÷2/5。","steps":["2/5 的倒数是 5/2。","把除法写成 3/4×5/2。"],"answer":"15/8。"},"practices":[{"type":"number","text":"3/4÷2/5＝？","answer":1.875,"check":"(3/4)/(2/5)","hint":"除以 2/5，改成乘 5/2。","solution":"3/4×5/2＝15/8。","unit":""},{"type":"number","text":"5/6÷5＝？","answer":0.16666666666666666,"check":"(5/6)/5","hint":"5 可以写成 5/1，它的倒数是 1/5。","solution":"5/6×1/5＝1/6。","unit":""},{"type":"number","text":"20 本书占全部书的 2/5，全部有多少本？","answer":50,"check":"20/(2/5)","hint":"已知部分量与分率，求整体用除法。","solution":"全部书×2/5＝20，所以全部书＝20÷2/5＝50。","unit":"本"}]},{"id":"2.7","chapter":"2","title":"分数与小数的互化","goal":"把分数化成小数，把有限小数化成分数，并认识循环现象。","concept":["分数化成小数，用分子除以分母。结果可能是有限小数，也可能是无限循环小数。","有限小数化成分数，先写成分母为 10、100、1000 等的分数，再约分。"],"formula":"0.45＝45/100＝9/20","pitfall":"不能把循环小数的某个截断值当成准确的原分数。","prerequisites":["2.1","2.2"],"example":{"question":"把 3/8 化成小数。","steps":["分子除以分母：3÷8。","进行除法，得到 0.375。"],"answer":"3/8＝0.375。"},"practices":[{"type":"number","text":"3/8 化成小数是多少？","answer":0.375,"check":"3/8","hint":"用 3 除以 8。","solution":"3÷8＝0.375。","unit":""},{"type":"number","text":"0.45 化成最简分数是多少？","answer":0.45,"check":"45/100","hint":"先写成 45/100，再约分。","solution":"45/100 的分子分母同时除以 5，得到 9/20。","unit":""},{"type":"choice","text":"1/6 化成小数属于哪一种？","options":["有限小数","无限循环小数","整数"],"answer":"无限循环小数","hint":"计算 1÷6，观察后面的数字。","solution":"1/6＝0.1666…，数字 6 重复，是无限循环小数。","unit":""}]},{"id":"2.8","chapter":"2","title":"分数、小数的四则混合运算","goal":"遵守运算顺序，选择分数或小数统一计算。","concept":["先算括号，再算乘除，最后算加减；同级运算从左向右。","分数与小数混合时，可以按题目选择统一成分数或有限小数，让计算更方便。"],"formula":"括号 → 乘除 → 加减；同级从左到右","pitfall":"没有括号时不能只按从左到右计算；循环小数不宜随意截断后参与精确计算。","prerequisites":["2.4","2.5","2.6","2.7"],"example":{"question":"计算 1/2＋3/4×2/3。","steps":["先算乘法：3/4×2/3＝1/2。","再算加法：1/2＋1/2＝1。"],"answer":"1。"},"practices":[{"type":"number","text":"1/2＋3/4×2/3＝？","answer":1,"check":"1/2+3/4*2/3","hint":"先乘，后加。","solution":"3/4×2/3＝1/2，再加 1/2 得 1。","unit":""},{"type":"number","text":"（0.5＋1/4）÷3/4＝？","answer":1,"check":"(0.5+1/4)/(3/4)","hint":"先算括号；0.5＝1/2。","solution":"括号内为 3/4，3/4÷3/4＝1。","unit":""},{"type":"number","text":"1−（2/5＋0.25）＝？","answer":0.35,"check":"1-(2/5+0.25)","hint":"先算括号，0.25＝1/4。","solution":"2/5＋1/4＝13/20，1−13/20＝7/20。","unit":""}]},{"id":"2.9","chapter":"2","title":"分数运算的应用","goal":"找到单位“1”，区分求部分与求整体，并检查分率的标准量。","concept":["“占谁的几分之几”中的“谁”通常是比较的标准量，也叫单位“1”。","已知整体求部分用乘法；已知部分及对应分率求整体用除法。连续变化时，后一次的标准量可能改变。"],"formula":"部分量＝整体量×分率；整体量＝部分量÷分率","pitfall":"“全长的 1/2”和“剩余长度的 1/2”对应的标准量不同。","prerequisites":["2.5","2.6","2.8"],"example":{"question":"18 本故事书占全部书的 3/10，全部有多少本？","steps":["把全部书看作单位“1”。","已知部分量 18 和分率 3/10，求整体用除法。"],"answer":"18÷3/10＝60 本。"},"practices":[{"type":"number","text":"120 本书中，故事书占 1/4，故事书有多少本？","answer":30,"check":"120*1/4","hint":"求整体的几分之几，用乘法。","solution":"120×1/4＝30 本。","unit":"本"},{"type":"number","text":"18 本故事书占全部书的 3/10，全部有多少本？","answer":60,"check":"18/(3/10)","hint":"已知部分求整体，用除法。","solution":"18÷3/10＝60 本。","unit":"本"},{"type":"number","text":"绳子长 30 米，先剪去全长的 1/3，再剪去剩余长度的 1/2，最后剩多少米？","answer":10,"check":"30*(1-1/3)*(1-1/2)","hint":"两次的标准量不同。","solution":"第一次剩 30×2/3＝20 米，第二次剩 20×1/2＝10 米。","unit":"米"}]},{"id":"3.1","chapter":"3","title":"比的意义","goal":"理解比的前项、后项和比值，把比写成除法。","concept":["两个数相除也可以表示它们的比。a∶b 中，a 是前项，b 是后项，a÷b 是比值。后项不能为零。","比有顺序，前后项互换通常会改变比值。两个量有单位时，先注意是否需要统一单位。"],"formula":"a∶b＝a÷b（b≠0）","pitfall":"比“2∶3”表示一种关系，比值“2/3”是一个数，不能把二者当成完全相同的写法要求。","prerequisites":["2.1","2.6"],"example":{"question":"12∶18 的比值是多少？","steps":["用前项除以后项：12÷18。","写成分数 12/18，再约分。"],"answer":"比值是 2/3。"},"practices":[{"type":"number","text":"12∶18 的比值是多少？","answer":0.6666666666666666,"check":"12/18","hint":"用前项除以后项。","solution":"12÷18＝12/18＝2/3。","unit":""},{"type":"number","text":"两个数的比是 4∶5，前一个数为 8，后一个数是多少？","answer":10,"check":"8/4*5","hint":"前项对应 4 份，每份是 8÷4。","solution":"每份 2，后项 5 份，所以为 2×5＝10。","unit":""},{"type":"number","text":"15∶6 的比值是多少？","answer":2.5,"check":"15/6","hint":"注意前后顺序。","solution":"15÷6＝5/2＝2.5。","unit":""}]},{"id":"3.2","chapter":"3","title":"比的基本性质","goal":"保持比值不变，化简整数、小数和分数的比。","concept":["比的前项和后项同时乘或除以同一个非零数，比值不变。","化成最简整数比时，先把小数或分数的比转成整数比，再约去公因数。"],"formula":"a∶b＝(a×k)∶(b×k)，k≠0","pitfall":"最简整数比的前后项要是互素的整数，不能只写一个比值代替。","prerequisites":["3.1","1.5","2.2"],"example":{"question":"把 1.5∶2.5 化成最简整数比。","steps":["前后项同时乘 10，得到 15∶25。","再同时除以 5。"],"answer":"最简整数比为 3∶5。"},"practices":[{"type":"number","text":"18∶24 化成最简整数比为 3∶□，□ 是多少？","answer":4,"check":"24/6","hint":"前后项同时除以 6。","solution":"18∶24＝3∶4，所以填 4。","unit":""},{"type":"number","text":"1.5∶2.5 化成最简整数比为 □∶5，□ 是多少？","answer":3,"check":"1.5*2","hint":"先同时乘 10，再约分。","solution":"15∶25＝3∶5，所以填 3。","unit":""},{"type":"number","text":"2/3∶4/5 化成最简整数比为 5∶□，□ 是多少？","answer":6,"check":"(4/5)*15/2","hint":"前后项同时乘 15，先化成整数比。","solution":"先得 10∶12，再同时除以 2，得到 5∶6。","unit":""}]},{"id":"3.3","chapter":"3","title":"比例","goal":"识别相等的两个比，用比例的性质求未知项。","concept":["表示两个比相等的式子叫比例。可以先计算两边比值，判断是否相等。","在比例里，两外项的积等于两内项的积，可以据此求未知的项。"],"formula":"a∶b＝c∶d → a×d＝b×c","pitfall":"比例与单独一个比不同；列比例前要保证对应的量与顺序一致。","prerequisites":["3.1","3.2"],"example":{"question":"2∶3＝8∶x，求 x。","steps":["两外项的积等于两内项的积：2x＝3×8。","两边除以 2，得到 x＝12。"],"answer":"x＝12。"},"practices":[{"type":"number","text":"2∶3＝8∶x，x 是多少？","answer":12,"check":"3*8/2","hint":"外项积等于内项积。","solution":"2x＝24，所以 x＝12。","unit":""},{"type":"number","text":"x∶5＝9∶15，x 是多少？","answer":3,"check":"5*9/15","hint":"15x＝5×9。","solution":"15x＝45，所以 x＝3。","unit":""},{"type":"number","text":"6∶10＝9∶□，□ 是多少？","answer":15,"check":"10*9/6","hint":"6×□＝10×9。","solution":"□＝90÷6＝15。","unit":""}]},{"id":"3.4","chapter":"3","title":"百分比的意义","goal":"把百分比、分数和小数互相转换，理解比较标准。","concept":["百分比表示一个数是另一个数的百分之几，用 % 表示。百分比描述的是关系，不带米、千克等具体单位。","百分数化成小数时除以 100，小数化成百分数时乘以 100 并写上 %。"],"formula":"35%＝35/100＝0.35＝7/20","pitfall":"0.8% 是 0.008，不是 0.8；百分号已经表示除以 100。","prerequisites":["2.7","3.1"],"example":{"question":"7/20 化成百分数是多少？","steps":["把分母化成 100：7/20＝35/100。","写成百分数。"],"answer":"35%。"},"practices":[{"type":"number","text":"7/20＝多少 %？输入百分号前的数。","answer":35,"check":"7/20*100","hint":"先化成分母为 100 的分数。","solution":"7/20＝35/100＝35%。","unit":"%"},{"type":"number","text":"25% 化成小数是多少？","answer":0.25,"check":"25/100","hint":"百分号表示除以 100。","solution":"25÷100＝0.25。","unit":""},{"type":"number","text":"0.8% 化成小数是多少？","answer":0.008,"check":"0.8/100","hint":"不是去掉百分号，要再除以 100。","solution":"0.8÷100＝0.008。","unit":""}]},{"id":"3.5","chapter":"3","title":"百分比的应用","goal":"判断求部分、求整体还是求变化率，应用到折扣与增减。","concept":["求一个量的百分之几，用标准量乘百分率；已知部分及其百分率求标准量，用除法。","增长率或减少率，通常以变化前的量为标准。折扣表示现价是原价的十分之几，例如八折是原价的 80%。"],"formula":"变化率＝变化量÷原来的量；现价＝原价×折扣","pitfall":"“减少了20%”与“减少到20%”含义不同；八折表示付款80%，不是付款20%。","prerequisites":["3.4","2.9"],"example":{"question":"原价 150 元，打八折，需要付多少元？","steps":["八折＝80%＝0.8。","求原价的 80%，用 150×0.8。"],"answer":"需要付 120 元。"},"practices":[{"type":"number","text":"原价 150 元的书包打八折，现价多少元？","answer":120,"check":"150*0.8","hint":"八折表示付原价的 80%。","solution":"150×80%＝120 元。","unit":"元"},{"type":"number","text":"原有 120 本书，增加了原来数量的 10%，现在多少本？","answer":132,"check":"120*(1+0.1)","hint":"新增量与原数量要相加。","solution":"新增 12 本，现有 120＋12＝132 本。","unit":"本"},{"type":"number","text":"价格从 200 元降到 160 元，减少了多少 %？","answer":20,"check":"(200-160)/200*100","hint":"用减少的量除以原价。","solution":"减少 40 元，40÷200＝20%。","unit":"%"}]},{"id":"3.6","chapter":"3","title":"等可能事件","goal":"在各结果等可能时，用结果数量理解事件发生的可能性。","concept":["当每种基本结果出现的可能性相同时，可以用“符合条件的结果数÷全部可能结果数”表示事件发生的可能性。","可能性在 0 和 1 之间；一次试验的实际结果不一定等于这个比例。必须先确认基本结果等可能。"],"formula":"等可能时：事件的可能性＝符合条件的结果数÷总结果数","pitfall":"不能只看有哪些颜色，要看各颜色的数量，也要说明随机抽取条件。","prerequisites":["2.1","3.1"],"example":{"question":"袋中 3 个红球、2 个蓝球，球大小质地相同，随机摸一球，摸到红球的可能性是多少？","steps":["全部球为 3＋2＝5 个，每个球被摸到的机会相同。","符合红球条件的有 3 个。"],"answer":"可能性为 3/5。"},"practices":[{"type":"number","text":"3 红球、2 蓝球，大小质地相同，随机摸一球，红球的可能性是多少？","answer":0.6,"check":"3/(3+2)","hint":"符合条件的数量除以总数。","solution":"红球 3 个，共 5 个，所以为 3/5。","unit":""},{"type":"number","text":"掷一枚均匀六面骰子，点数为偶数的可能性是多少？","answer":0.5,"check":"3/6","hint":"偶数点数是 2、4、6。","solution":"共有 6 种等可能结果，符合条件的有 3 种，所以为 3/6＝1/2。","unit":""},{"type":"number","text":"抛一枚正反面机会相同的硬币，正面朝上的可能性是多少？","answer":0.5,"check":"1/2","hint":"两种等可能结果中，正面占一种。","solution":"可能性为 1/2；这不表示抛两次就必定恰好出现一次正面。","unit":""}]},{"id":"4.1","chapter":"4","title":"圆的周长","goal":"分清半径与直径，正确使用周长公式和长度单位。","concept":["半径从圆心连到圆上，直径经过圆心连接圆上两点。一条直径的长度是半径的两倍。","圆的周长与直径的比是圆周率 π；周长可以用 π 乘直径，或用 2π 乘半径。"],"formula":"d＝2r；C＝πd＝2πr","pitfall":"已知半径时不能只乘 π；周长是长度，不用平方单位。","prerequisites":["3.1"],"example":{"question":"半径 3 厘米的圆，π 取 3.14，周长是多少？","steps":["先求直径：2×3＝6 厘米。","周长＝3.14×6。"],"answer":"18.84 厘米。"},"practices":[{"type":"number","text":"圆半径 4 厘米，π 取 3.14，周长多少厘米？","answer":25.12,"check":"2*3.14*4","hint":"先把半径乘 2。","solution":"C＝2πr＝2×3.14×4＝25.12 厘米。","unit":"厘米"},{"type":"number","text":"圆直径 10 米，π 取 3.14，周长多少米？","answer":31.4,"check":"3.14*10","hint":"这次已知直径，不需要再乘 2。","solution":"C＝πd＝3.14×10＝31.4 米。","unit":"米"},{"type":"number","text":"车轮半径 0.5 米，滚动 5 圈（不打滑），π 取 3.14，前进多少米？","answer":15.7,"check":"2*3.14*0.5*5","hint":"每圈前进一个周长。","solution":"一圈 3.14 米，5 圈为 3.14×5＝15.7 米。","unit":"米"}]},{"id":"4.2","chapter":"4","title":"弧长","goal":"把圆心角对应的弧看成整个圆周的一部分。","concept":["圆上的一段曲线叫弧。圆心角占一周角 360° 的几分之几，相应弧长就占圆周长的几分之几。","先求整个圆的周长，再乘圆心角与 360° 的比。弧长不是连接弧两端的直线长度。"],"formula":"弧长＝2πr × 圆心角/360°","pitfall":"弧长是曲线的长度，圆心角是角度，二者单位不同。","prerequisites":["4.1","3.1","2.5"],"example":{"question":"半径 6 厘米、圆心角 60° 的弧，π 取 3.14，求弧长。","steps":["整个圆周长为 2×3.14×6＝37.68 厘米。","60° 占 360° 的 1/6，弧长也取周长的 1/6。"],"answer":"37.68÷6＝6.28 厘米。"},"practices":[{"type":"number","text":"半径 6 厘米、圆心角 60°，π 取 3.14，弧长多少厘米？","answer":6.28,"check":"2*3.14*6*60/360","hint":"把圆周长乘 60/360。","solution":"2×3.14×6×60/360＝6.28 厘米。","unit":"厘米"},{"type":"number","text":"直径 12 厘米、圆心角 90°，π 取 3.14，弧长多少厘米？","answer":9.42,"check":"3.14*12*90/360","hint":"90° 对应整个圆周的 1/4。","solution":"3.14×12×1/4＝9.42 厘米。","unit":"厘米"},{"type":"number","text":"半径 10 米、圆心角 180°，π 取 3.14，弧长多少米？","answer":31.4,"check":"2*3.14*10*180/360","hint":"180° 是一周角的一半。","solution":"2×3.14×10×1/2＝31.4 米。","unit":"米"}]},{"id":"4.3","chapter":"4","title":"圆的面积","goal":"用半径求圆的面积，理解平方单位与半径变化的影响。","concept":["圆的面积表示圆内部区域的大小。它与半径的平方成正比，可以用 πr² 求出。","已知直径时，先除以 2 得到半径，再代入公式。面积的单位是平方厘米、平方米等。"],"formula":"S＝πr²＝π×r×r","pitfall":"周长公式 2πr 不能拿来算面积；半径变成两倍，面积会变成四倍。","prerequisites":["4.1","2.5"],"example":{"question":"半径 4 厘米的圆，π 取 3.14，面积是多少？","steps":["半径为 4 厘米。","先计算半径平方：4×4＝16。","再乘 π：3.14×16。"],"answer":"50.24 平方厘米。"},"practices":[{"type":"number","text":"圆半径 4 厘米，π 取 3.14，面积多少平方厘米？","answer":50.24,"check":"3.14*4*4","hint":"半径要乘两次。","solution":"S＝3.14×4×4＝50.24 平方厘米。","unit":"平方厘米"},{"type":"number","text":"圆直径 10 米，π 取 3.14，面积多少平方米？","answer":78.5,"check":"3.14*(10/2)**2","hint":"先把直径变成半径。","solution":"半径为 5 米，面积为 3.14×5×5＝78.5 平方米。","unit":"平方米"},{"type":"number","text":"一个圆的半径变成原来的 2 倍，面积变成原来的几倍？","answer":4,"check":"2**2","hint":"比较半径平方的变化。","solution":"新面积为 π×(2r)²＝4πr²，所以变成 4 倍。","unit":"倍"}]},{"id":"4.4","chapter":"4","title":"扇形的面积","goal":"理解扇形占整个圆的比例，区分面积与弧长。","concept":["两条半径和它们所夹的弧围成扇形。圆心角占 360° 的几分之几，扇形面积就占整个圆面积的几分之几。","先求圆面积，再乘圆心角与 360° 的比。不要把面积公式与弧长公式混用。"],"formula":"扇形面积＝πr² × 圆心角/360°","pitfall":"同样乘角度比例，弧长用圆周长，扇形面积用圆面积。","prerequisites":["4.2","4.3","2.5"],"example":{"question":"半径 6 厘米、圆心角 60° 的扇形，π 取 3.14，求面积。","steps":["整个圆面积为 3.14×6×6＝113.04 平方厘米。","60° 占一周角的 1/6，面积也取 1/6。"],"answer":"113.04÷6＝18.84 平方厘米。"},"practices":[{"type":"number","text":"半径 6 厘米、圆心角 60° 的扇形，π 取 3.14，面积多少平方厘米？","answer":18.84,"check":"3.14*6*6*60/360","hint":"先求圆面积，再取 1/6。","solution":"3.14×6×6×60/360＝18.84 平方厘米。","unit":"平方厘米"},{"type":"number","text":"半径 4 厘米、圆心角 90° 的扇形，π 取 3.14，面积多少平方厘米？","answer":12.56,"check":"3.14*4*4*90/360","hint":"90° 对应圆面积的 1/4。","solution":"3.14×4×4×1/4＝12.56 平方厘米。","unit":"平方厘米"},{"type":"number","text":"半径 10 米、圆心角 180° 的扇形，π 取 3.14，面积多少平方米？","answer":157,"check":"3.14*10*10*180/360","hint":"半圆的面积是圆面积的一半。","solution":"3.14×10×10×1/2＝157 平方米。","unit":"平方米"}]}],"questionLinks":{"books":"2.9","discount":"3.5","circle":"4.1","ratio":"3.1"}};
